-- ---------------------------------------------------------------- 2. history
-- Closed bookings are inserted directly with their final status. The BEFORE INSERT
-- trigger still validates every row (capacity, players, age, hours, tier limits) and
-- prices it; overlap checks apply only to active rows, and none of these overlap anyway.

-- ---------------------------------------------------------------- 3. late fees (BR-16)
UPDATE Rentals_Reservations
   SET late_fee = fn_calculate_late_fee(booking_id, returned_at)
 WHERE status = 'Completed' AND returned_at > reserved_end + INTERVAL 15 MINUTE;

-- ---------------------------------------------------------------- 4. inspections (BR-17/18)
-- Allowed for Completed bookings; trg_insp_after_insert copies the condition to the box.

-- ---------------------------------------------------------------- 5. restock + copy statuses
-- Every lost piece has been replaced except the last return of copy 2.
UPDATE Missing_Pieces mp
  JOIN Return_Inspections ri ON ri.inspection_id = mp.inspection_id
   SET mp.restocked_at = LEAST(ri.inspected_at + INTERVAL 1 DAY, NOW())
 WHERE mp.inspection_id <> 253;
-- Inspections moved copies around while history loaded: put every box back on the
-- shelf, then set the fixture copies explicitly.
UPDATE Game_Copies SET status = 'Available';
UPDATE Game_Copies SET status = 'Missing_Pieces' WHERE copy_id = 2;
UPDATE Game_Copies SET status = 'Under_Repair'   WHERE copy_id = 23;
UPDATE Game_Copies SET status = 'Retired'        WHERE copy_id = 24;

-- ---------------------------------------------------------------- 6. payments (PAY-01/02)
-- Payments go in BEFORE the future reservations: otherwise every member with history
-- owes more than Rs 500 and sp_create_reservation (correctly) refuses them all (BR-13).
SELECT booking_id, total_amount, ELT(1 + booking_id % 3, 'Cash', 'Card', 'UPI'),
       COALESCE(returned_at, reserved_start)
  FROM Rentals_Reservations
 WHERE status IN ('Completed', 'Cancelled', 'No_Show') AND total_amount > 0
   AND booking_id NOT IN (8, 65, 101, 135, 154, 196, 218, 234, 261, 274, 314)
 ORDER BY booking_id;
-- A few members still owe a little (at most Rs 120 each) on one visit
SELECT booking_id, total_amount - 100, 'UPI', returned_at
  FROM Rentals_Reservations WHERE booking_id = 8 AND total_amount > 100;
SELECT booking_id, total_amount - 50, 'UPI', returned_at
  FROM Rentals_Reservations WHERE booking_id = 65 AND total_amount > 50;
SELECT booking_id, total_amount - 80, 'UPI', returned_at
  FROM Rentals_Reservations WHERE booking_id = 101 AND total_amount > 80;
SELECT booking_id, total_amount - 50, 'UPI', returned_at
  FROM Rentals_Reservations WHERE booking_id = 135 AND total_amount > 50;
SELECT booking_id, total_amount - 50, 'UPI', returned_at
  FROM Rentals_Reservations WHERE booking_id = 154 AND total_amount > 50;
SELECT booking_id, total_amount - 80, 'UPI', returned_at
  FROM Rentals_Reservations WHERE booking_id = 196 AND total_amount > 80;
SELECT booking_id, total_amount - 100, 'UPI', returned_at
  FROM Rentals_Reservations WHERE booking_id = 218 AND total_amount > 100;
SELECT booking_id, total_amount - 100, 'UPI', returned_at
  FROM Rentals_Reservations WHERE booking_id = 261 AND total_amount > 100;

-- ---------------------------------------------------------------- 7. live rows
-- Overdue take-home: inserted as Checked_In (trg_rr_after_insert marks the copy Rented),
-- then moved to Overdue - the same transition ev_mark_overdue makes.
                                  reserved_start, reserved_end, checked_in_at, status)
VALUES (17, NULL, 6, 'Take_Home', NULL, TIMESTAMP(CURRENT_DATE - INTERVAL 3 DAY, '12:00:00'), TIMESTAMP(CURRENT_DATE - INTERVAL 1 DAY, '12:00:00'), TIMESTAMP(CURRENT_DATE - INTERVAL 3 DAY, '12:10:00'), 'Checked_In');
UPDATE Rentals_Reservations SET status = 'Overdue' WHERE booking_id = LAST_INSERT_ID();
                                  reserved_start, reserved_end, checked_in_at, status)
