-- ---------------------------------------------------------------- summary
SELECT (SELECT COUNT(*) FROM Customers) AS customers,
       (SELECT COUNT(*) FROM Game_Copies) AS copies,
       (SELECT COUNT(*) FROM Rentals_Reservations) AS bookings,
       (SELECT COUNT(*) FROM Return_Inspections) AS inspections,
       (SELECT COUNT(*) FROM Missing_Pieces) AS missing_piece_rows,
       (SELECT COUNT(*) FROM Payments) AS payments,
       (SELECT COUNT(*) FROM Booking_Audit_Log) AS audit_rows;
